// what the compiler builds, and what you write by hand for non-async CPS
enum Step { Call(Req, Box<dyn FnOnce(Resp, Step) -> Step>), Done(Resp) }

fn run(mut s: Step) -> Resp {                       // the driver / trampoline
    loop { match s {
        Step::Done(r)  => return r,
        Step::Call(q, k) => s = k.send(q),           // k is the continuation
    }}
}

// async is the same thing with the state machine generated for you
async fn total(ids: &[u64]) -> u64 { ids.iter().sum() }   // a Future<Output = u64>
